using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF 9.
        // Preserve the old property name for backward compatibility with existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key" in EF 9.
        // Use a value generator or shadow property to preserve the old "Blog|{key}" id format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);

        // Breaking change 3: HasIndex() now throws for Cosmos in EF 9 (indexes are managed by Cosmos itself).
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Breaking change 4: Sync I/O now throws by default in EF 9 Cosmos provider.
        // Opt back in if you have sync call sites (see SyncJob.cs fix below).
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

